  await shot('e16-launcher-collapsed-dark');await click('#btnSidebarExpand');
  await click('.work-panel-launcher-row[data-tool="btnTree"]');
  await waitFor(`!document.querySelector('#modal').hidden`);await shot('e17-branch-dialog-dark');await key('ESC');
  check('E branch launcher uses the existing modal and Escape leaves the workbench open',await read(`document.querySelector('#modal').hidden&&!document.querySelector('#rightPane').hidden`));
