  await shot('e02-specs-dark');
  await click('.specs-doc-item[data-spec-id="'+'2'.repeat(32)+'"]');
  check('E document selection reads its own original production transport',await read(`eSpecRequests.at(-1)==='2'.repeat(32)`));
  await click('#btnSpecsSplit');
  await waitFor(`!!document.querySelector('#workbenchSpecsPane')`);
  check('E Specs and Changes retain the existing split layout',await read(`document.querySelector('.workbench-split').dataset.workbenchMode==='split'&&!!document.querySelector('#workbenchChangesPane .chg-head')`));
  await shot('e03-split-dark');
  await click('#workPanelHome');
  check('E real return-to-tools action clears the split surface, not the draft',await read(`!document.querySelector('.workbench-split')&&document.querySelector('.work-panel-empty')&&document.querySelector('#input')===eInput&&eInput.value.includes('阶段 E')`));
  await click('.work-panel-launcher-row[data-tool="navChanges"]');
  await waitFor(`!!document.querySelector('.chg-row')`);
  check('E Changes retains status rows and real review/refresh controls',await read(`document.querySelectorAll('.chg-row').length>=3&&!!document.querySelector('#rightPane .chg-head button')`));
  await shot('e04-changes-dark');
  await read(`ETheme.setThemePreference('light')`);await shot('e05-changes-light');
  await click('#workPanelHome');await shot('e06-launcher-light');await nativeShot('e06-launcher-light');
  await read(`eSpecs='empty'`);await click('.work-panel-launcher-row[data-tool="btnSpecs"]');
